package glitch

import data.glitch_lib

# Patterns for detecting CWE-353 weaknesses
insecure_protocols := {"http", "ftp", "smtp", "telnet", "smtps", "pop3", "imap"}
insecure_auth := {"none", "anonymous", "null", "disabled", false}
insecure_encryption := {"disabled", "none", "null", false}
insecure_tls_versions := {"", "null", "none", "1.0", "1.1", false}
insecure_checksums := {"none", "null", "disabled", false, ""}
insecure_policies := {"permissive", "none", "disabled", false}

# Check for insecure protocol configurations
check_insecure_protocol(attr) {
    attr.name in {"protocol", "encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_protocols
} else {
    attr.name in {"protocol", "encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_auth
} else {
    attr.name in {"protocol", "encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_encryption
} else {
    attr.name in {"protocol", "encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_tls_versions
} else {
    attr.name in {"protocol", "encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_policies
} else {
    attr.name in {"encryption", "authentication", "tls_version", "security_policy"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name in {"anonymous", "enable_data_validation", "hash_validation"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name in {"authentication", "encryption", "protocol"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check for missing or disabled checksums
check_missing_checksums(attr) {
    attr.name in {"checksum_algorithm", "hash_validation", "enable_data_validation"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_checksums
} else {
    attr.name in {"checksum_algorithm", "hash_validation", "enable_data_validation"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name in {"checksum_algorithm", "hash_validation", "enable_data_validation"}
    attr.value.ir_type == "Null"
} else {
    attr.name in {"object_storage", "sync_replication"}
    attr.value.ir_type == "Hash"
    check_hash_insecure_integrity(attr.value)
}

# Check for insecure data pipeline configurations
check_insecure_pipelines(attr) {
    attr.name in {"message_integrity", "acknowledgment_mode", "use_tls"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_checksums
} else {
    attr.name in {"message_integrity", "acknowledgment_mode", "use_tls"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "data_pipeline"
    attr.value.ir_type == "Hash"
    check_hash_insecure_integrity(attr.value)
}

# Check for insecure default configurations
check_insecure_defaults(attr) {
    attr.name in {"enforce_tls", "default_security", "allow_plain_text", "auto_checksum"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name in {"enforce_tls", "default_security", "allow_plain_text", "auto_checksum"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_policies
} else {
    attr.name in {"enforce_tls", "default_security", "allow_plain_text", "auto_checksum"}
    attr.value.ir_type == "Null"
}

# Check for custom protocol issues
check_custom_protocols(attr) {
    attr.name in {"custom_protocol", "protocol_options", "data_integrity"}
    attr.value.ir_type == "Hash"
    check_hash_insecure_integrity(attr.value)
} else {
    attr.name in {"custom_protocol", "protocol_options", "data_integrity"}
    attr.value.ir_type == "String"
    val := lower(attr.value.value)
    val in insecure_checksums
} else {
    attr.name in {"custom_protocol", "protocol_options", "data_integrity"}
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name in {"custom_protocol", "protocol_options", "data_integrity"}
    attr.value.ir_type == "Null"
}

# Helper function to check hash values for insecure integrity settings
check_hash_insecure_integrity(hash_value) {
    hash_value.ir_type == "Hash"
    some key, val in hash_value.value
    key.ir_type == "String"
    lower(key.value) in {"checksum", "integrity_check", "validation", "security", "encryption"}
    val.ir_type == "String"
    lower(val.value) in insecure_checksums
} else {
    hash_value.ir_type == "Hash"
    some key, val in hash_value.value
    key.ir_type == "String"
    lower(key.value) in {"checksum", "integrity_check", "validation", "security", "encryption"}
    val.ir_type == "Boolean"
    val.value == false
} else {
    hash_value.ir_type == "Hash"
    some key, val in hash_value.value
    key.ir_type == "String"
    lower(key.value) in {"checksum", "integrity_check", "validation", "security", "encryption"}
    val.ir_type == "Null"
}

# Main detection rule
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for any of the insecure patterns
    check_insecure_protocol(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Configuration uses insecure protocols or missing integrity validation mechanisms (CWE-353)"
    }
}

